svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 400" role="img" aria-label="원본 주요 진단 항목별 행 수"><rect width="1100" height="400" fill="#fff"/><text x="30" y="35" font-size="22" fill="#203249" font-family="NanumGothic,Malgun Gothic,sans-serif">원본 검수 335,000행의 주요 진단 항목</text>']
for i,(label,v) in enumerate(chart_rows):
 y=75+i*55;width=v/max(x[1] for x in chart_rows)*620;svg.extend([f'<text x="30" y="{y+24}" font-size="16" fill="#203249" font-family="NanumGothic,Malgun Gothic,sans-serif">{E(label)}</text>',f'<rect x="260" y="{y}" width="{width}" height="35" rx="3" fill="#2457a6"/>',f'<text x="{270+width}" y="{y+24}" font-size="16" fill="#203249">{v:,}</text>'])
